    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val1, uint _val2) public payable {
        bool reverted1;
        c.SetMinSum(_val1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }
        uint afterMinSum1 = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted2;
        c.SetMinSum(_val2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted2 = true; } else { reverted2 = false; }
        uint afterMinSum2 = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!reverted1 && afterMinSum1 == _val1 && !reverted2 && afterMinSum2 == _val2);
    }

    receive() external payable {}
}

