pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val1, uint256 _val2) internal {
        bool reverted1;
        try c.SetMinSum(_val1) { reverted1 = false; } catch { reverted1 = true; }
        uint256 afterMinSum1;
        try c.MinSum() returns (uint256 __r) { afterMinSum1 = __r; } catch { return; }
        bool reverted2;
        try c.SetMinSum(_val2) { reverted2 = false; } catch { reverted2 = true; }
        uint256 afterMinSum2;
        try c.MinSum() returns (uint256 __r) { afterMinSum2 = __r; } catch { return; }
        assertTrue(!reverted1 && afterMinSum1 == _val1 && !reverted2 && afterMinSum2 == _val2);
    }

    function testFuzz_run(uint256 _val1, uint256 _val2) public {
        _run(_val1, _val2);
    }

    receive() external payable {}
}
